\begin{definition}[Dissipative weak (DW) solution]
Let the initial data satisfy 
\begin{equation*}
    \varrho_0 \in L^1(\Omega), \mathbf{m}_0 \in L^1(\Omega;\mathbb{R}^d), E_0 = E(\varrho_0,\mathbf{m}_0,S_0) \text{ and } \int_{\Omega} E(\varrho_0,\mathbf{m}_0,S_0) \dbx{} < \infty. 
\end{equation*}
We say that $[\varrho,\mathbf{m},S]$ is a DW solution to the Euler system in $[0,T) \times \Omega$, $0<T< \infty$, if the following holds:
\begin{itemize}
    \item \textbf{Regularity.} $(\varrho,\mathbf{m},S)$ belongs to the class
    \begin{gather*}
        \varrho \in C_{\text{weak,loc}}\paraL{[0,T);L^{\gamma}(\Omega)}, \mathbf{m} \in C_{\text{weak,loc}}\paraL{[0,T);L^{\frac{2\gamma}{\gamma+1}}(\Omega;\mathbb{R}^d)}, \\
        S \in L^{\infty}\paraL{0,T;L^{\gamma}(\Omega)} \ \cap \ BV_{\text{weak}}\paraL{[0,T);L^{\gamma}(\Omega)}, \\
        \int_{\Omega} E(\varrho,\mathbf{m},S) (t,\cdot) \dbx{} \leq \int_{\Omega} E(\varrho_0,\mathbf{m}_0,S_0) \dbx{} \text{ for any } 0\leq t < T. 
    \end{gather*}
    \item \textbf{Continuity equation.} The integral identity
    \begin{equation*}
        \int_0^T \int_{\Omega} \left[ \varrho \partial_t \varphi + \mathbf{m} \cdot \nabla_x \varphi \right] \dbx{} \dt{} = - \int_{\Omega} \varrho_0 \varphi(0,\cdot) \dbx{}
    \end{equation*}
    holds for any test function $\varphi \in C_c^1\paraL{[0,T) \times \Omega}$.
    \item \textbf{Momentum equation.} The integral identity
    \begin{multline*}
        \int_0^T \int_{\Omega} \left[ \mathbf{m} \cdot \partial_t \boldsymbol{\varphi} + \mathds{1}_{\varrho>0} \frac{\mathbf{m}\otimes\mathbf{m}}{\varrho} : \nabla_x \boldsymbol{\varphi} + p(\varrho,S) \divx{} \boldsymbol{\varphi} \right] \dbx{} \dt{} \\ 
        = - \int_0^T \int_{\Omega} \nabla_x \boldsymbol{\varphi} : \text{d}\mathfrak{R}(t) \dbx{} - \int_{\Omega} \mathbf{m}_0 \cdot \boldsymbol{\varphi}(0,\cdot) \dbx{}
    \end{multline*}
    holds for any test function $\boldsymbol{\varphi} \in C_c^1\paraL{[0,T) \times \Omega;\mathbb{R}^d}$. Here, $\mathfrak{R}$ is the so-called Reynolds stress defect, such that
    \begin{equation*}
        \mathfrak{R} \in L^{\infty}\paraL{(0,T);\mathcal{M}^+\paraL{\Omega;\mathbb{R}_{\text{sym}}^{d\times d}}}. 
    \end{equation*}
    \item \textbf{Entropy inequality.} The inequality
    \begin{gather*}
        \left[\int_{\Omega} S \varphi \dx{}\right]_{t=\tau_1-}^{t=\tau_2+} \geq \int_{\tau_1}^{\tau_2} \int_{\Omega} \left[ S \partial_t \varphi + \left\langle \mathcal{V}_{t,x};\mathrm{1}_{\widetilde{\varrho}>0} \paraL{\widetilde{S}\frac{\widetilde{\mathbf{m}}}{\widetilde{\varrho}}} \right\rangle \cdot \nabla_x \varphi \right] \dbx{} \dt{}, \\ 
        S(0-,\cdot) = S_0
    \end{gather*}
    holds for any $0 \leq \tau_1 \leq \tau_2 < T$, any test function $\varphi \in C_c^1\paraL{[0,T) \times \Omega}$, $\varphi \geq 0$. Here, $\left\{ \mathcal{V}_{t,x} \right\}_{(t,x) \in (0,T) \times \Omega}$ is a parametrized probability (Young) measure,
    \begin{gather*}
        \mathcal{V}_{t,x} \in L^{\infty}\paraL{(0,T) \times \Omega;\mathcal{P}\paraL{\mathbb{R}^{d+2}}}, \mathbb{R}^{d+2} = \left\{ \widetilde{\varrho} \in \mathbb{R}, \widetilde{\mathbf{m}} \in \mathbb{R}^d, \widetilde{S} \in \mathbb{R}  \right\}; \\
        \left\langle \mathcal{V}; \widetilde{\varrho} \right\rangle = \varrho, \left\langle \mathcal{V}; \widetilde{\mathbf{m}} \right\rangle = \mathbf{m}, \left\langle \mathcal{V}; \widetilde{S} \right\rangle = S. 
    \end{gather*}
    \item \textbf{Compatibility of the energy and Reynolds stress defects.} There exists a non-increasing function $\mathcal{E}:[0,T) \to [0,\infty)$ such that
    \begin{eqnarray*}
        \mathcal{E}(0-) &=& \int_{\Omega} E(\varrho_0,\mathbf{m}_0,S_0) \dbx{}, \\
        \mathcal{E}(\tau+) &=& \int_{\Omega} E(\varrho,\mathbf{m},S)(\tau,\cdot) \dbx{} + \mathfrak{E} \text{ for any } 0 \leq \tau < T.
    \end{eqnarray*}
    Here $\mathfrak{E} \in L^{\infty}\paraL{(0,T;\mathcal{M}^+\paraL{\Omega}}$ is the energy defect satisfying
    \begin{equation*}
        \min \{ 2, d (\gamma - 1) \} \mathfrak{E} \leq \text{trace} [\mathfrak{R}] \leq \max \{ 2, d (\gamma - 1) \} \mathfrak{E}. 
    \end{equation*}
\end{itemize}
\end{definition}

Specifically, the DW solutions $[\varrho,\mathbf{m},S]$ with initial data $[\varrho_0,\mathbf{m}_0,S_0]$ are selected if they satisfy
\begin{multline}
\label{functionals}
    \int_0^\infty \exp (-\lambda t)\beta (\varrho(t,\cdot),\mathbf{m}(t,\cdot),S(t,\cdot)) \dt{}  \\  
    \leq \int_0^\infty \exp (-\lambda t) \beta (\tilde{\varrho}(t,\cdot),\tilde{\mathbf{m}}(t,\cdot),\tilde{S}(t,\cdot)) \dt{}, \ \forall [\tilde{\varrho},\tilde{\mathbf{m}},\tilde{S}] \in \mathcal{U} [\varrho_0,\mathbf{m}_0,S_0].
\end{multline}
Here $\beta$ is a bounded continuous function, $\lambda>0$, and $\mathcal{U} [\varrho_0,\mathbf{m}_0,S_0]$ denotes the set of all DW solutions emanating from the initial data $[\varrho_0,\mathbf{m}_0,S_0]$. By assigning special functions $\beta$, the admissible DW solutions can be selected. Nevertheless, different choices of $\beta$ and $\lambda$ may lead to different solution semiflows, and there is no further a priori guidance on how to select $\lambda$ and $\beta$. Thus, this semiflow selection cf.~\cite{BreitFeireislHofmanova2020,BreitFeireislHofmanova2020b} yields infinitely many selection steps.

In \cite{FeireislJungelLukacova2025}, Feireisl, J\"{u}ngel, Luk\'{a}\v{c}ov\'{a} proposed a two-step selection process in the class of DW solutions for the isentropic Euler system. This consists of minimising the following functionals. First, the energy functional 
\begin{equation*}
    \int_0^\infty \exp (-t) \mathcal{E}(t) \dt{}
\end{equation*}
is minimised. Here, $\mathcal{E}$ is a scalar, time-dependent function, the so-called total energy. In the convergence analysis of structure-preserving numerical methods, $\mathcal{E}$ is obtained as a weak$^*$ limit of an approximate sequence of energies $\int_\Omega E_n \dx{} = \int_\Omega \left(\frac{1}{2}\frac{\modL{\mathbf{m}_n}^2}{\varrho_n} + \frac{1}{\gamma-1}\varrho_n^\gamma\right)\dx{}$, for $n \to \infty$. We point out that the total energy $\mathcal{E}$ is, in general, not strictly convex. Note, however, that for admissible weak solutions the total energy reduces to the mean energy, i.e. $\mathcal{E}(t) = \int_\Omega E(\varrho,\mathbf{m})\dx{} \ (t)$ a.e. $t \in (0,T)$. Due to the thermodynamic stability imposed on the equations of state $E(\varrho,\mathbf{m})$ is strictly convex.  

As shown in \cite{FeireislJungelLukacova2025}, if a unique solution is selected in the first step, it is an admissible weak solution. Otherwise, we proceed with the second selection step and select a truly measure-valued solution by minimising a suitable strictly convex functional on the set of DW solutions selected in the first step. In \cite{FeireislJungelLukacova2025}, it was suggested to minimise
\begin{equation*}
    \int_0^\infty \exp (-t) \left[ \norm{\varrho}_{L^q(\Omega)}^q (t) + \norm{\mathbf{m}}_{L^q(\Omega)}^q (t) + \modL{\mathcal{E}(t)}^q \right] \dt ,
\end{equation*}
where $1<q\leq \frac{2\gamma}{\gamma +1}$.

For the full Euler system, the following two-step selection was proposed by Feireisl, Luk\'{a}\v{c}ov\'{a} in \cite{feireisllukacova2025}
\begin{gather*}
    \int_0^\infty \exp (-t) \paraL{ \int_\Omega -S(t,\cdot) \ \dx{} } \dt{}, \\
    \int_0^\infty \exp (-t) \paraL{\int_\Omega E(\varrho,\mathbf{m}, S) (t,\cdot) \ \dx{}} \dt{}. 
\end{gather*}

By combining the above two functionals, the following one-step selection, i.e., the minimisation of 
\begin{equation*}
    \int_0^{\infty} \exp (-t) \int_{\Omega} \left( E\left( \widetilde{\varrho},\widetilde{\mathbf{m}},\widetilde{S} \right) - \overline{\vartheta} \widetilde{S} \right) \, \dx{} \ \dt{} 
\end{equation*}
was also proposed in \cite{feireisllukacova2025}. It represents the Bregman distance between $(\widetilde{\varrho}, \widetilde{\mathbf{m}}, \widetilde{S})$ and the equilibrium solution $(\overline{\varrho},0,\overline{\theta})$ that maximizes the entropy production, $\overline{\varrho} = \frac{1}{\modL{\Omega}} M_0$. Here $\overline{\vartheta} = \frac{\mathcal{E}_0}{c_v M_0}, \mathcal{E}_0 = \int_{\Omega} \widetilde{E}(t=0,\mathbf{x}) \dx{}, M_0 = \int_{\Omega} \widetilde{\varrho}(t=0,\mathbf{x}) \dx{}, c_v = 2.5$. We refer to \cite{feireisllukacova2025} for further details on the derivation.

First, we examine the entropy production of the numerical solutions.
Following the discussion in \Cref{Sec: Introduction}, we approximate the entropy of DW solutions using a \textit{Ces\`{a}ro} average, and consequently define
\begin{align*}
	\mathcal{I}_{\widetilde{S}}(t) &= \int_{\Omega}\widetilde{S}(t,\mathbf{x}) \,\mathrm{d} \mathbf{x}, \nonumber\\
	D_S(t) &=\mathcal{I}_{\widetilde{S}}(t) - \mathcal{I}_{\widetilde{S}}(0), \nonumber
\end{align*}
where $D_S(t)$ represents the entropy production at time $t$.
Next, the total energy and mean energy of the numerical solutions are defined as
\begin{align*}
	\mathcal{I}_{\widetilde{E}}(t) &=  \int_{\Omega}\widetilde{E}(t,\mathbf{x}) \,\mathrm{d} \mathbf{x}, \nonumber\\
	\mathcal{I}_{\widehat{E}}(t) &= \int_{\Omega}E\left( \widetilde{\varrho},\widetilde{\mathbf{m}},\widetilde{S} \right)(t,\mathbf{x}) \,\mathrm{d} \mathbf{x}, \nonumber
\end{align*}
and the energy defect at time $t$ is given by
\begin{align*}
	\mathcal{D}_E(t) &= \mathcal{I}_{\widetilde{E}}(t) - \mathcal{I}_{\widehat{E}}(t). \nonumber
\end{align*}

We next consider the functionals introduced in \eqref{functionals}.
The functions defined above can serve as candidates for the function $\beta$.
Owing to the boundedness of the approximate solutions, $\beta$ can also be chosen as an appropriate norm.
Accordingly, we define
\begin{align*}
	%\mathcal{J}_{\widetilde{E}}(t) &= \int_{0}^t \mathcal{I}_{\widetilde{E}}(\tau) \mathrm{d} \tau \nonumber\\
	\mathcal{J}_{\widetilde{S}}(t) &= \int_{0}^t \mathcal{I}_{\widetilde{S}}(\tau) \mathrm{d} \tau \nonumber\\
	\mathcal{J}_{\widehat{E}}(t) &= \int_{0}^t \mathcal{I}_{\widehat{E}}(\tau) \mathrm{d} \tau \nonumber\\
	\mathcal{J}_{(\widetilde{\varrho},\widetilde{\mathbf{m}},\widetilde{S})}(t) &= \int_{0}^t \left( \norm{\widetilde{\varrho}}^q_{L^q}  + \norm{\widetilde{\mathbf{m}}}^q_{L^q} + \norm{\widetilde{S}}^q_{L^q} \right) \mathrm{d} \tau, \nonumber
\end{align*}
where $q=1.1$. Correspondingly, we consider the time-weighted integrals in \eqref{functionals}
\begin{align}
	%\mathcal{F}_{\widetilde{E}}(t) &= \int_{0}^t e^{-\tau} \mathcal{I}_{\widetilde{E}}(\tau) \mathrm{d} \tau \nonumber\\
	\mathcal{F}_{\widetilde{S}}(t) &= \int_{0}^t e^{-\tau} \mathcal{I}_{\widetilde{S}}(\tau) \mathrm{d} \tau \nonumber\\
    \mathcal{F}_{\widehat{E}}(t) &= \int_{0}^t e^{-\tau} \mathcal{I}_{\widehat{E}}(\tau) \mathrm{d} \tau \nonumber\\
	\mathcal{F}_{(\widetilde{\varrho},\widetilde{\mathbf{m}},\widetilde{S})}(t) &= \int_{0}^t e^{-\tau} \left( \norm{\widetilde{\varrho}}^q_{L^q}  + \norm{\widetilde{\mathbf{m}}}^q_{L^q} + \norm{\widetilde{S}}^q_{L^q} \right) \mathrm{d} \tau \nonumber.
\end{align}
As suggested in \cite{feireisllukacova2025}, we also consider the following functional,
\begin{equation*}
    \mathcal{A}(t) = \int_0^{t} \int_{\Omega} \left( E\left( \widetilde{\varrho},\widetilde{\mathbf{m}},\widetilde{S} \right) - \overline{\vartheta} \widetilde{S} \right) \, \dx \ \dt = \mathcal{J}_{\widehat{E}}(t) - \overline{\vartheta} \mathcal{J}_{\widetilde{S}}(t). 
\end{equation*}
We recall that $\overline{\vartheta} = \frac{\mathcal{E}_0}{c_v M_0}, \mathcal{E}_0 = \int_{\Omega} \widetilde{E}(t=0,\mathbf{x}) \dx, M_0 = \int_{\Omega} \widetilde{\varrho}(t=0,\mathbf{x}) \dx, c_v = 2.5$.

\textit{Entropy-related functionals}
\begin{enumerate} 
    \item Maximising $\mathcal{I}_{\widetilde{S}}(t)$: DVBFV~0 and RKDG~0 dominate globally at all times. At t=10, DVBFV~0, RKDG~0, DVBFV~1, RKDG~2 and RKDG~1 are the top 5 methods that maximise $\mathcal{I}_{\widetilde{S}}(t)$, see \Cref{tab: I_tilS}. 
    \item Maximising $\mathcal{J}_{\widetilde{S}}(t)$: DVBFV~0 and RKDG~0 dominate globally at all times. At t=10, DVBFV~0, RKDG~0, DVBFV~1, RKDG~1 and RKDG~2 are the top 5 methods that maximise $\mathcal{J}_{\widetilde{S}}(t)$, see \Cref{tab: J_tilS}. 
    \item Maximising $\mathcal{F}_{\widetilde{S}}(t)$: RKDG~0 and DVBFV~0 dominate globally at all times. At t=10, RKDG~0, DVBFV~0, DVBFV~1, RKDG~1 and RKDG~4 are the top 5 methods that maximise $\mathcal{F}_{\widetilde{S}}(t)$, see \Cref{tab: F_tilS}. 
    \item Maximising $D_{S}(t)$: DVBFV~0 and RKDG~0 dominate globally at all times. At t=10, DVBFV~0, RKDG~0, DVBFV~1, RKDG~2 and RKDG~1 are the top 5 methods that maximise $D_S(t)$, see \Cref{tab: D_S}.   
\end{enumerate}
From the discussion, it is clear that the methods DVBFV~0, RKDG~0, and DVBFV~1 yield the required maximisation of entropy-related functionals. \\

\textit{Energy-related functionals}
\begin{enumerate}
    \item Minimising $\mathcal{I}_{\widehat{E}}(t)$: At t=10, VFV~8, VFV~1, VFV~6, VFV~4 and VFV~2 are the top 5 methods that minimise $\mathcal{I}_{\widehat{E}}(t)$, see \Cref{tab: I_hatE}.  
    \item Minimising $\mathcal{J}_{\widehat{E}}(t)$: At t=10, VFV~6, DGSEM~1, VFV~1, VFV~4 and VFV~8 are the top 5 methods that minimise $\mathcal{J}_{\widehat{E}}(t)$, see \Cref{tab: J_hatE}.  
    \item Minimising $\mathcal{F}_{\widehat{E}}(t)$: At t=10, VFV~0, DGSEM~1, DGSEM~2, VFV~6 and VFV~8 are the top 5 methods that minimise $\mathcal{F}_{\widehat{E}}(t)$, see \Cref{tab: F_hatE}. 
    \item Maximising $\mathcal{D}_{E}(t)$: At t=10, VFV~8, VFV~1, VFV~6, VFV~4 and VFV~2 are the top 5 methods that maximise $\mathcal{D}_{E}(t)$, see \Cref{tab: D_E}.  
\end{enumerate}
From our discussion of the energy-related functionals, we cannot infer which methods yield minimisation, but we can observe that higher-order methods yield smaller mean energy and maximise the energy defect.

The subscripts $L$ and $R$ represent the states left and right of the interface $i+\frac{1}{2}$, respectively. The values of $\lambda^\pm$ are chosen such that the numerical scheme maintains the positivity of pressure and density at all time levels. 
\begin{eqnarray*}
    \lambda^+_{i+\frac{1}{2}}=\max\left(\frac{1}{2}(V^\perp_L+a_L+\modL{V^\perp_L+a_L}),\frac{1}{2}(V^\perp_R+a_R+\modL{V^\perp_R+a_R})\right),\\
    \lambda^-_{i+\frac{1}{2}}=\min\left(\frac{1}{2}(V^\perp_L-a_L-\modL{V^\perp_L-a_L}),\frac{1}{2}(V^\perp_R-a_R-\modL{V^\perp_R-a_R})\right),\\
\end{eqnarray*}
where $V^\perp = (u \hat{i}+v\hat{j})\cdot n_{i+\frac{1}{2}}$ is the fluid velocity normal to the edge $i+\frac{1}{2}$ and $a$ is the local speed of sound. The definitions of $\mathbf{f_{eq\pm}}$ can be obtained by using the moment relations in \eqref{eq:m}.

\par \noindent \textbf{Higher order numerical scheme} \\
To get second-order accuracy in space, a linear polynomial reconstruction of $\mathbf{U}$ has been utilised in every cell. The gradients are calculated using the Green-Gauss method, and a positivity limiter suggested by Zhang \cite{Zhang_2017} is used to make sure that the reconstructed $\mathbf{U}$ also preserves the positivity of density and pressure. To get the higher order accuracy in time, a strong stability preserving Runge Kutta method of 2$^{\text{nd}}$ order accuracy is employed. Let the first order update formula given above be $\mathscr{T_E}(\mathbf{U}_i^n)$, then the SSPRK2 update is,
\begin{equation*}
    \begin{array}{rcl}
         \mathbf{U}^*_i&=&\mathscr{T_E}({\mathbf{U}}_i^n),  \\
         \mathbf{U}_i^{n+1}&=&\frac{1}{2}\mathbf{U}_i^n+\frac{1}{2}\mathscr{T_E}(\mathbf{U}_i^*).
    \end{array}
\end{equation*}
Both the first-order and second-order numerical schemes preserve the positivity of density and pressure, given that the initial conditions also have the same property.

Here, $w_i$ are the LGL quadrature weights, $D$ is the polynomial derivative matrix with $D_{ij} = l^{'}_j (\xi_i)$  and $J_k = \Delta x_k / 2$ is the Jacobian of transformation. Following this notation, the entropy-stable DGSEM~\cite{chen2017entropy} can then be written as,
\begin{equation}\label{eqn:DGSEM}
    J_k \frac{d \mathbf{U}^k_i}{d t} +  \sum_{j=0}^N 2D_{ij} \mathbf{G}_k^{*}(ij) + \frac{\delta_{iN}}{w_N}\left(\widetilde{\mathbf{G}}^k_R -   \mathbf{G}^k_N\right) -  \frac{\delta_{i0}}{w_0}\left(\widetilde{\mathbf{G}}^k_L -   \mathbf{G}^k_0\right)= 0,
\end{equation}
where $\mathbf{G}^{*}(ij)$ is the two-point symmetric entropy conservative flux (also referred to as the volume flux) and $\widetilde{\mathbf{G}}_I$ is the entropy-stable numerical flux evaluated at the element edges (also referred to as the surface flux). We choose the entropy conservative and kinetic energy preserving flux of Chandrashekar~\cite{chandrashekar2013kinetic} as volume flux and local Lax-Friedrichs flux as the surface flux.\\
The entropy-stable DGSEM scheme~\eqref{eqn:DGSEM} is stabilised following the blending limiter approach of Hennemann et al.~\cite{hennemann2021provably}. In this approach, the higher order DG scheme~\eqref{eqn:DGSEM} is blended with a lower order entropy-stable finite volume (FV) scheme derived on subcells formed within the element. The size of subcells is determined by the quadrature weights in each dimension, and the FV scheme interprets the nodal DG values as the subcell averages. The lower-order scheme for $N+1$ subcells in an element $\Omega_k$ is written as
\begin{equation*}
    J_k  \frac{d \mathbf{U}^{k}_j}{d t} + \frac{1}{w_j}\left( \widetilde{\mathbf{G}}^k_{(j,j+1)} - \widetilde{\mathbf{G}}^k_{(j-1,j)} \right) = 0,\quad j\in \{0,1,\dots,N\}.
\end{equation*}
The numerical flux $\widetilde{\mathbf{G}}$ (also referred to as the blending flux) should be entropy-stable, and we choose the local Lax-Friedrichs flux for our simulations. The element-wise blending of higher order and lower order schemes can be written as

and the element-wise blending factor $\alpha \in [0,1]$ is computed from the shock indicator. According to the procedure described in~\cite{hennemann2021provably}, the blending factor $\alpha$ is a function of the highest mode energy indicator $ \mathbb{E}$ and polynomial order dependent threshold value $\mathbb{T}(N)$. The energy indicator is defined based on the modal energy of the shock indicator quantity $\phi$ as
\begin{equation*}
    e = \max \left(  \frac{\hat{\phi}_N^2}{\sum_{j=0}^N \hat{\phi}_j^2} , \frac{\hat{\phi}_{N-1}^2}{\sum_{j=0}^{N-1} \hat{\phi}_j^2} \right),
\end{equation*}
where $\hat{\phi}_j$ are the modal coefficients of $\phi$. The threshold value is defined as $f (N) = 0.5\cdot 10^{-1.8(N+1)^{\frac{1}{4}}}$ and the blending factor function with sharpness factor $s = 9.21024$ is given as
\begin{equation*}
    \alpha = \frac{1}{1+\exp(\frac{-s}{f}\left(e - f\right))}.
\end{equation*}
Further, a clipping procedure is performed on $\alpha$ to clear the incidents in the choice of pure lower-order or higher-order configurations as
\begin{equation*}
\Tilde{\alpha} = \begin{cases}
    0, \quad & \text{if}\quad \alpha < \alpha_{min}\\
    \alpha, \quad & \text{if}\quad \alpha_{min} \leq \alpha \leq 1 - \alpha_{min}\\
    1, \quad & \text{if}\quad 1 - \alpha_{min} < \alpha
\end{cases}; \ \alpha = \min(\Tilde{\alpha}, \alpha_{max}),
\end{equation*}
followed by element-wise smoothing of $\alpha$, see~\cite{hennemann2021provably} for more details. The shock indicator quantity is chosen as $\phi = \varrho p$, and the tuning parameters are taken as $\alpha_{min} = 0.0001$ and $\alpha_{max} = 0.001$  for all the simulations. We also use the scaling limiter of Zhang and Shu~\cite{zhang2010positivity} to ensure the positivity of the density and pressure.
